1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import com.fasterxml.jackson.annotation.JsonProperty;
4	import com.fasterxml.jackson.annotation.JsonPropertyOrder;
5	
6	/**
7	 * Immutable structured audit event emitted on a successful owner create, alongside the plain audit
8	 * line. {@link AuditOwnerCreated} serializes it with the project's Jackson {@code ObjectMapper} — the
9	 * same serializer the {@code rest/dto} DTOs use — to a single-line JSON object with fields in the
10	 * order the spec lists them: {@code {"seq":..,"ownerId":..,"memberId":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
11	 *
12	 * <p>The {@code memberId} slot carries the owner's <strong>primary identifier</strong>, read from
13	 * {@link org.springframework.samples.petclinic.model.Owner#primaryIdentifier()} — the unified member id.
14	 *
15	 * <p>{@code seq} is a monotonically increasing integer across creates (see {@link AuditOwnerCreated}).
16	 */
17	@JsonPropertyOrder({ "seq", "ownerId", "memberId", "membershipLevel", "event" })
18	public record OwnerCreatedEvent(long seq, int ownerId, String memberId, Integer membershipLevel) {
19	
20	    /** The fixed event marker distinguishing this structured event from other AUDIT lines. */
21	    public static final String EVENT = "OWNER_CREATED";
22	
23	    /** The constant event marker, exposed so it serializes as the {@code event} field. */
24	    @JsonProperty("event")
25	    public String event() {
26	        return EVENT;
27	    }
28	}
