5	import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
6	import org.springframework.samples.petclinic.rest.function.common.Hashes;
7	import org.springframework.samples.petclinic.rest.function.common.Localities;
8	
9	/**
10	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where {@code REGION}
11	 * is the region code derived from the owner's postcode (see {@link Localities#ofPostcode(String)}),
12	 * {@code FY} is the 2-digit fiscal year of the {@code registrationDate}, {@code HASH8} is the first 8
13	 * upper-case hex characters of SHA-256 over the owner's normalized telephone concatenated with their
14	 * last name, and {@code CHK} is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}
15	 * (e.g. {@code NSW261A2B3C4D7}). Apart from that check digit the id is a pure function of postcode,
16	 * registration date, telephone and last name.
17	 *
18	 * <p>Wired after {@link NormalizeOwnerTelephone} (so the telephone read here is already in E.164 form)
19	 * and after {@link DefaultOwnerRegistrationDate} (so the fiscal year is known), and every value derived
20	 * from the member id — the create audit line and the read-model locality and owner segment — reflects
21	 * this region-and-hash identity.
22	 */
23	public class AssignOwnerMemberId {
24	
25	    /** Length of the hash segment: the first 8 upper-case hex characters of the SHA-256 digest. */
26	    private static final int HASH_LENGTH = 8;
27	
28	    public void service(@Val Owner owner) {
29	        String region = Localities.ofPostcode(owner.getPostcode());
30	        int fy = FiscalYear.yy(owner.getRegistrationDate());
31	        String hash8 = Hashes.sha256UpperHex(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
32	        owner.setMemberId(MemberId.format(region, fy, hash8));
33	    }
34	}
