1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	import java.util.stream.Collectors;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * De-duplicates the owner's {@code memberId} against existing owners. The id assigned by
12	 * {@link AssignOwnerMemberId} is (apart from its check digit) a pure function of postcode, registration
13	 * date, telephone and last name, so two distinct owners can in principle compute the same id. When the
14	 * computed id already belongs to an existing owner, this step appends {@code -<n>} with the smallest
15	 * {@code n} of 2 or more that makes it unique (e.g. {@code NSW261A2B3C4D7} → {@code NSW261A2B3C4D7-2}),
16	 * guaranteeing distinct owners always receive distinct member ids.
17	 *
18	 * <p>Wired after {@link AssignOwnerMemberId} and before the create is saved, so the existing owners read
19	 * here never include this owner.
20	 */
21	public class DeduplicateOwnerMemberId {
22	
23	    /** The smallest suffix appended on a collision. */
24	    private static final int FIRST_SUFFIX = 2;
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String base = owner.getMemberId();
28	        Set<String> existing = ownerRepository.findAll().stream()
29	                .map(Owner::getMemberId)
30	                .collect(Collectors.toSet());
31	        if (!existing.contains(base)) {
32	            return;
33	        }
34	        String unique;
35	        for (int n = FIRST_SUFFIX; existing.contains(unique = MemberId.withSuffix(base, n)); n++) {
36	            // advance to the next suffix until the id is unique
37	        }
38	        owner.setMemberId(unique);
39	    }
40	}
