1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.rest.function.common.Localities;
4	import org.springframework.samples.petclinic.rest.function.common.Luhn;
5	
6	/**
7	 * The single definition of an owner's {@code memberId} format — {@code <REGION><FY><HASH8><CHK>},
8	 * the region code, the 2-digit fiscal year, the 8-character hash and a single Luhn check digit,
9	 * concatenated with no separator (e.g. {@code NSW261A2B3C4D7}). Co-locates construction
10	 * ({@link #format}) and read-back ({@link #regionOf}) so both agree on the layout and cannot drift
11	 * apart, the same idiom {@link IdentityKey} uses for the identity key.
12	 *
13	 * <p>{@code CHK} is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}
14	 * (the region and hash letters are ignored by {@link Luhn#checkDigit}). It unifies what used to be the
15	 * separate {@code customerCode}, {@code membershipNumber} and {@code checkDigit}.
16	 *
17	 * <p>Shared by {@link AssignOwnerMemberId} (which builds the id) and the owner mapper (which reads the
18	 * region back out as the owner's locality). Public because the mapper lives in another package.
19	 */
20	public final class MemberId {
21	
22	    /** The character separating the base id from a de-duplication suffix. */
23	    private static final char SEPARATOR = '-';
24	
25	    /**
26	     * The member id for the given region, 2-digit fiscal year and hash segment —
27	     * {@code <REGION><FY><HASH8><CHK>} where {@code CHK} is the Luhn check digit over the digits of
28	     * {@code <REGION><FY><HASH8>}.
29	     */
30	    public static String format(String region, int fiscalYearYy, String hash8) {
31	        String base = region + String.format("%02d", fiscalYearYy) + hash8;
32	        return base + Luhn.checkDigit(base);
33	    }
34	
35	    /**
36	     * The de-duplicated form of {@code base} — the base member id with {@code -<n>} appended — used to
37	     * keep otherwise-colliding ids distinct (see {@link DeduplicateOwnerMemberId}).
38	     */
39	    public static String withSuffix(String base, int n) {
40	        return base + SEPARATOR + n;
41	    }
42	
43	    /**
44	     * The region segment of a {@code <REGION><FY><HASH8><CHK>} member id — the leading run of letters
45	     * before the first digit (the fiscal year) — or {@link Localities#UNKNOWN} when the id is absent,
46	     * blank or does not start with a region code.
47	     */
48	    public static String regionOf(String memberId) {
49	        if (memberId == null || memberId.isBlank()) {
50	            return Localities.UNKNOWN;
51	        }
52	        int i = 0;
53	        while (i < memberId.length() && !Character.isDigit(memberId.charAt(i))) {
54	            i++;
55	        }
56	        return i == 0 ? Localities.UNKNOWN : memberId.substring(0, i);
57	    }
58	
59	    private MemberId() {
60	    }
61	}
